css:
.my-custom-box {
  width: 100%;
  height: 100%;
  background: #ffffff;
  border-radius: 7vw;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  box-sizing: border-box;
  padding: 3.5vw 4vw 2.5vw;
}

/* 顶部用户信息 */
.tweet-header {
  display: flex;
  align-items: center;
  gap: 2.5vw;
  flex-shrink: 0;
}

.tweet-avatar {
  width: 13vw;
  height: 13vw;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.tweet-user {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.tweet-name-row {
  display: flex;
  align-items: center;
  gap: 1vw;
}

.tweet-name {
  font-size: 4vw;
  font-weight: 700;
  color: #0f1419;
}

.verified-icon {
  width: 3.5vw;
  height: 3.5vw;
  object-fit: contain;
}

.tweet-handle {
  font-size: 3vw;
  color: #536471;
  margin-top: 0.3vw;
}

.tweet-actions {
  display: flex;
  align-items: center;
  gap: 2vw;
  flex-shrink: 0;
}

.follow-btn {
  background: #ffffff;
  border: 1px solid #cfd9de;
  border-radius: 10vw;
  padding: 1vw 3vw;
  font-size: 3vw;
  color: #0f1419;
  font-weight: 600;
  cursor: pointer;
}

.more-btn {
  font-size: 4vw;
  color: #536471;
}

/* 正文 */
.tweet-body {
  margin-top: 2.5vw;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 1.5vw;
}

.tweet-text {
  margin: 0;
  font-size: 3.5vw;
  font-weight: 700;
  color: #0f1419;
  line-height: 1.4;
}

.tweet-translate {
  margin: 0;
  font-size: 2.8vw;
  color: #536471;
}

.translate-link {
  color: #1d9bf0;
  font-weight: 600;
}

.tweet-translate-text {
  margin: 0;
  font-size: 2.8vw;
  color: #0f1419;
}

.tweet-tag {
  display: inline-block;
  background: #e7e7e7;
  border-radius: 10vw;
  padding: 0.6vw 2.5vw;
  font-size: 2.8vw;
  color: #536471;
  align-self: flex-start;
}

/* 图片 */
.tweet-image-wrap {
  margin-top: 2.5vw;
  flex: 1;
  min-height: 0;
  border-radius: 3.5vw;
  overflow: hidden;
}

.tweet-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* 分割线 */
.tweet-divider {
  width: 100%;
  height: 1px;
  background: rgba(0,0,0,0.08);
  margin-top: 2.5vw;
  flex-shrink: 0;
}

/* 底部互动栏 */
.tweet-footer {
  display: flex;
  align-items: center;
  gap: 6vw;
  margin-top: 2vw;
  flex-shrink: 0;
}

.footer-item {
  display: flex;
  align-items: center;
  gap: 1.5vw;
  font-size: 3vw;
  color: #536471;
}

.footer-icon {
  width: 3.8vw;
  height: 3.8vw;
  object-fit: contain;
}
